def sha(b):
    return hashlib.sha256(b).hexdigest()

def main():
    if not os.path.exists(TARGET):
        sys.exit("ERR  %s not found.\n     cd ~/Desktop/forge-daily-brief first, and check you are on gh-pages." % TARGET)
    cur = open(TARGET, "rb").read()
    got = sha(cur)
    if got == POST:
        print("OK   %s is ALREADY patched. Nothing to do." % TARGET)
    elif got != PRE:
        print("STOP %s is not the version this patch was built against." % TARGET)
        print("     expected %s" % PRE)
        print("     found    %s" % got)
        print("     Nothing was changed. Send both hashes to Claude before doing anything else.")
        sys.exit(1)
    else:
        new = gzip.decompress(base64.b64decode(PAYLOAD))
        if sha(new) != POST:
            sys.exit("STOP embedded payload is corrupt - the paste was truncated. Nothing was changed.")
        stamp = datetime.datetime.now().strftime("%Y%m%d-%H%M%S")
        backup = "%s.install17.bak-%s" % (TARGET, stamp)
        open(backup, "wb").write(cur)
        open(TARGET, "wb").write(new)
        if sha(open(TARGET, "rb").read()) != POST:
            open(TARGET, "wb").write(cur)
            sys.exit("STOP write verification failed. %s was restored. Nothing changed." % TARGET)
        if TARGET.endswith(".py"):
            try:
                import ast
                ast.parse(open(TARGET, encoding="utf-8").read())
            except Exception as e:
                open(TARGET, "wb").write(cur)
                sys.exit("STOP patched file did not parse (%s). Restored. Nothing changed." % e)
        print("OK   %s patched." % TARGET)
        print("     backup: %s" % backup)

    if EXTRA_NAME:
        open(EXTRA_NAME, "wb").write(gzip.decompress(base64.b64decode(EXTRA)))
        print("OK   %s written." % EXTRA_NAME)

    print("")
    print("Next, one command per line:")
    print("  git add planner.html CHANGELOG.md")
    print("  git commit -m \"install17: relative planner link + changelog\"")
    print("  git pull --rebase")
    print("  git push")
    print("")
    print("No workflow run needed. planner.html is hand-maintained.")

if __name__ == "__main__":
    main()
